public class InterpreterDemonstration {
    // A cold method executed infrequently will likely remain interpreted
    public static int computeCold(int a, int b) {
        return a + b;
    }

    // A hot loop will trigger the interpreter's back-edge counter, 
    // leading to JIT compilation (OSR - On-Stack Replacement)
    public static void main(String[] args) {
        int accumulator = 0;
        for (int i = 0; i < 100_000; i++) {
            accumulator += computeCold(i, i);
        }
        System.out.println("Computed Result: " + accumulator);
    }
}
